const ctx = $json;
const p = ctx.patient || {};
const clinic = ctx.clinic || {};
const ready = !!(p.name && (p.phone || p.email));
const day = $now.format('yyyy-LL-dd');
const leadKey = `${clinic.clinic_id}|${p.phone || p.email || 'nocontact'}|handoff|${day}`;

let reply;
if (ready) {
  reply = `Thanks ${p.name} — I've let our clinic team know you'd like to speak with someone. They'll follow up with you as soon as they can. Is there anything else I can note for them?`;
} else {
  reply = (ctx.next_question && ctx.next_question.trim()) ? ctx.next_question : `Of course — I'll connect you with our team. Could you share your full name and the best phone number or email to reach you?`;
}

const row = {
  tab: 'Escalations', operation: 'upsert', sheet_id: clinic.sheet_id, lead_key: leadKey,
  timestamp: ctx.timestamp || $now.toISO(), session_id: ctx.session_id, patient_name: p.name || '',
  phone: p.phone || '', email: p.email || '', issue_type: 'human_handoff', urgency: ctx.urgency || 'medium',
  summary: (clinic.test_mode ? '[TEST] ' : '') + (ctx.summary || ctx.user_message),
  staff_notified: ready, sms_sent: false, status: ready ? 'New' : 'Collecting',
  notes: p.reason || ''
};

const emailBody = `Request type: Human handoff\nUrgency: ${ctx.urgency}\nPatient: ${p.name}\nPhone: ${p.phone || '-'}\nEmail: ${p.email || '-'}\nReason: ${p.reason || ctx.summary}\n\nOriginal message: "${ctx.user_message}"\n\nRecommended next action: Follow up with the patient.`;
const email = { to: clinic.staff_email, subject: `[${clinic.clinic_name}] Human handoff request — ${p.name}`, body: (clinic.test_mode ? '[TEST MODE]\n' : '') + emailBody, reply_to: p.email || '' };

const sms = { to: p.phone, body: `Hi ${p.name}, thanks for reaching out to ${clinic.clinic_name}. A team member will follow up with you soon.`, message_type: 'handoff_received', from: clinic.twilio_from, enabled: clinic.sms_enabled_patient, session_id: ctx.session_id, sheet_id: clinic.sheet_id };

return { json: { ...ctx, bot_response: reply, _ready: ready, _row: row, _email: email, _sms: sms } };
